    // ── Staff attendance table with date filter ──────────────────────────────
    $sa_date = $_GET['sa_date'] ?? date('Y-m-d');
    $staff_attendance = [];
    try {
        $saq = $pdo->prepare("
            SELECT 
                s.name AS staff_name,
                s.staff_uuid,
                s.role,
                MIN(CASE WHEN g.check_type = 'Check-In' THEN g.timestamp END) AS clock_in,
                MAX(CASE WHEN g.check_type = 'Check-Out' THEN g.timestamp END) AS clock_out,
                COUNT(CASE WHEN g.check_type = 'Check-In' THEN 1 END) AS check_in_count,
                COUNT(CASE WHEN g.check_type = 'Check-Out' THEN 1 END) AS check_out_count
            FROM staff s
            LEFT JOIN gate_attendance_logs g 
                ON g.person_uuid = s.staff_uuid 
                AND g.school_uuid = s.school_uuid
                AND DATE(g.timestamp) = ?
                AND g.status = 'Valid'
            WHERE s.school_uuid = ? AND s.status = 'Active'
            GROUP BY s.staff_uuid, s.name, s.role
            ORDER BY s.name ASC
        ");
        $saq->execute([$sa_date, $school_uuid]);
        $staff_attendance = $saq->fetchAll();
    } catch (Exception $e) {}

    // ── Visitor QR code handling ─────────────────────────────────────────────
