    <script src="https://cdn.jsdelivr.net/npm/jsqr@1.4.0/dist/jsQR.min.js"></script>
    <script>
    (function() {
        const video = document.getElementById('gsVideo');
        const canvas = document.getElementById('gsCanvas');
        const ctx = canvas.getContext('2d');
        const startBtn = document.getElementById('gsStartCam');
        const stopBtn = document.getElementById('gsStopCam');
        const resultBox = document.getElementById('gsResult');
        let stream = null, scanning = false, lastCode = '', lastTime = 0;

        function showResult(data) {
            const ok = data.success;
            const color = ok ? 'emerald' : (data.status === 'Expired' ? 'amber' : 'rose');
            resultBox.innerHTML = `<div class="p-3 rounded-xl border text-xs bg-${color}-500/10 border-${color}-500/20 text-${color}-400">
                <strong>${data.person_name || 'Unknown'}</strong> ${data.person_type ? '(' + data.person_type + ')' : ''}<br>
                ${data.check_type ? data.check_type + ' — ' : ''}${data.status || ''} ${data.time ? 'at ' + data.time : ''}<br>
                ${data.error || data.warning || ''}
            </div>`;
        }

        function logCode(code) {
            if (!code) return;
            fetch('api/gate-scan.php', {
                method: 'POST',
                headers: {'Content-Type': 'application/x-www-form-urlencoded'},
                body: 'code=' + encodeURIComponent(code)
            }).then(r => r.json()).then(showResult).catch(() => {
                resultBox.innerHTML = '<div class="p-3 rounded-xl border text-xs bg-rose-500/10 border-rose-500/20 text-rose-400">Network error logging scan.</div>';
            });
        }

        function tick() {
            if (!scanning) return;
            if (video.readyState === video.HAVE_ENOUGH_DATA) {
                canvas.width = video.videoWidth;
                canvas.height = video.videoHeight;
                ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
                const imageData = ctx.getImageData(0, 0, canvas.width, canvas.height);
                const code = window.jsQR ? jsQR(imageData.data, imageData.width, imageData.height) : null;
                if (code && code.data) {
                    const now = Date.now();
                    if (code.data !== lastCode || now - lastTime > 4000) {
                        lastCode = code.data; lastTime = now;
                        logCode(code.data);
                    }
                }
            }
            requestAnimationFrame(tick);
        }

        startBtn.addEventListener('click', function() {
            navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } }).then(function(s) {
                stream = s;
                video.srcObject = stream;
                video.play();
                scanning = true;
                startBtn.classList.add('hidden');
                stopBtn.classList.remove('hidden');
                requestAnimationFrame(tick);
            }).catch(function() {
                resultBox.innerHTML = '<div class="p-3 rounded-xl border text-xs bg-rose-500/10 border-rose-500/20 text-rose-400">Could not access camera — use manual entry instead.</div>';
            });
        });
        stopBtn.addEventListener('click', function() {
            scanning = false;
            if (stream) stream.getTracks().forEach(t => t.stop());
            stopBtn.classList.add('hidden');
            startBtn.classList.remove('hidden');
        });
    })();

